import click

@click.command()
@click.option('--{{arg_name}}', required=True, help='target {{arg_name}}')
@click.option('--count', default=1, type=int)
@click.option('--dry-run', is_flag=True)
def {{cmd_name}}({{arg_name}}, count, dry_run):
    """Run {{cmd_name}} on {{arg_name}}."""
    for i in range(count):
        if dry_run:
            click.echo(f'[dry] {i}: {{{arg_name}}}')
        else:
            click.echo(f'{i}: {{{arg_name}}}')

if __name__ == '__main__':
    {{cmd_name}}()
